class Dog:
    species = "Canis familiaris"   # class attribute — shared

    def __init__(self, name, age):
        self.name = name           # instance attribute
        self.age = age

    def bark(self):                # instance method
        return f"{self.name} says woof!"

    @classmethod
    def from_dict(cls, d):
        return cls(d["name"], d["age"])

dog = Dog("Rex", 5)
print(dog.bark())         # Rex says woof!
print(dog.species)        # Canis familiaris
print(Dog.from_dict({"name": "Max", "age": 3}).bark())  # Max says woof!

class Animal:
    def __init__(self, name):
        self.name = name
    def speak(self):
        raise NotImplementedError

class Dog(Animal):
    def speak(self):
        return f"{self.name} says woof!"

class Cat(Animal):
    def speak(self):
        return f"{self.name} says meow!"

for a in [Dog("Rex"), Cat("Whiskers")]:
    print(a.speak())  # polymorphism — same call, different behavior

import threading, time, requests

def fetch(url, results, idx):
    r = requests.get(url, timeout=5)
    results[idx] = r.status_code

urls = ["https://httpbin.org/get"] * 10
results = [None] * len(urls)
threads = [threading.Thread(target=fetch, args=(url, results, i)) for i, url in enumerate(urls)]
for t in threads: t.start()
for t in threads: t.join()
print(results)   # [200, 200, ..., 200] — concurrent HTTP

from functools import lru_cache
import time

# Without cache — exponential time
def fib_slow(n):
    return n if n < 2 else fib_slow(n-1) + fib_slow(n-2)

# With cache — O(n)
@lru_cache(maxsize=None)
def fib_fast(n):
    return n if n < 2 else fib_fast(n-1) + fib_fast(n-2)

start = time.perf_counter()
print(fib_fast(100), time.perf_counter() - start)   # instant
print(fib_slow(35), time.perf_counter() - start)    # ~3 seconds

# Cache info
print(fib_fast.cache_info())   # CacheInfo(hits=97, misses=101, maxsize=None, currsize=101)
